import Link from "next/link";
import { notFound } from "next/navigation";
import { requireAccountType } from "@/lib/auth/dal";
import { getVendorTransactionById } from "@/lib/api/vendor-orders";
import { getVendorProfile } from "@/lib/api/vendor-profile";
import { PrintButton } from "@/components/vendor/print-button";

export const instant = false; // requireAccountType reads cookies — genuinely dynamic

interface PageProps {
  params: Promise<{ id: string }>;
}

const TYPE_LABEL: Record<string, string> = { Sale: "Sale", Payout: "Payout", Fee: "Platform Fee" };

/** A print-friendly receipt for a single transaction — dashboard-shell.tsx's
 * header/sidebar are print:hidden, so printing this page shows only the
 * receipt itself. */
export default async function VendorTransactionReceiptPage({ params }: PageProps) {
  await requireAccountType("vendor", "/vendor/transactions");
  const { id } = await params;
  const [transaction, profile] = await Promise.all([getVendorTransactionById(id), getVendorProfile()]);
  if (!transaction) {
    notFound();
  }

  const isCredit = transaction.amount >= 0;

  return (
    <div className="mx-auto max-w-xl">
      <div className="flex items-center justify-between print:hidden">
        <Link href="/vendor/transactions" className="text-sm font-medium text-text-muted hover:text-ink">
          ← Transactions
        </Link>
        <PrintButton label="Print Receipt" />
      </div>

      <div className="mt-6 rounded-2xl border border-line bg-white p-8 shadow-[0_8px_30px_rgba(0,39,8,0.06)] print:mt-0 print:rounded-none print:border-0 print:p-0 print:shadow-none">
        <div className="flex items-start justify-between border-b border-line pb-6">
          <div>
            <p className="font-alata text-xl tracking-tight text-ink">VITALINK</p>
            <p className="mt-1 text-sm text-text-muted">{profile?.businessLegalName ?? "Vendor"}</p>
          </div>
          <div className="text-right">
            <p className="text-xs font-medium tracking-wide text-text-muted uppercase">Receipt</p>
            <p className="font-mono text-sm text-ink">{transaction.reference}</p>
          </div>
        </div>

        <div className="mt-6 space-y-4">
          <Row label="Date" value={new Date(transaction.createdAt).toLocaleString("en-NG", { dateStyle: "long", timeStyle: "short" })} />
          <Row label="Type" value={TYPE_LABEL[transaction.type] ?? transaction.type} />
          <Row label="Description" value={transaction.description} />
          <Row label="Reference" value={transaction.reference} mono />
        </div>

        <div className="mt-8 flex items-center justify-between rounded-xl bg-mint/60 px-5 py-4">
          <span className="text-sm font-medium text-ink">Amount</span>
          <span className={`font-[family-name:var(--font-newsreader)] text-2xl ${isCredit ? "text-verified" : "text-[#c0392b]"}`}>
            {isCredit ? "+" : "−"}N{Math.abs(transaction.amount).toLocaleString("en-NG")}
          </span>
        </div>

        <p className="mt-8 text-center text-xs text-text-muted">
          This receipt was generated by Vitalink for record-keeping purposes and is not a tax invoice.
        </p>
      </div>
    </div>
  );
}

function Row({ label, value, mono }: { label: string; value: string; mono?: boolean }) {
  return (
    <div className="flex items-center justify-between text-sm">
      <span className="text-text-muted">{label}</span>
      <span className={mono ? "font-mono text-xs text-ink" : "text-ink"}>{value}</span>
    </div>
  );
}
